1	package com.example.starter.redflush;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDateTime;
5	import java.util.HashMap;
6	import java.util.List;
7	import java.util.Map;
8	
9	import com.example.starter.common.ApiException;
10	import com.example.starter.credit.CreditService;
11	import com.example.starter.discrepancy.DiscrepancyGuard;
12	import com.example.starter.idempotency.IdempotencyService;
13	import com.fasterxml.jackson.core.JsonProcessingException;
14	import com.fasterxml.jackson.databind.ObjectMapper;
15	import org.springframework.dao.DuplicateKeyException;
16	import org.springframework.jdbc.core.JdbcTemplate;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.support.TransactionTemplate;
19	
20	/**
21	 * 红冲服务：红字信息表申请、购销双方确认与红票开具。
22	 * 规则：全额红冲须购方未入账或已取得购方确认；部分红冲按行项目拆分，
23	 * 累计红冲金额不得超过可红冲余额，恰红至余额为零合法；已全额红冲蓝票为终态，
24	 * 进一步红冲返回幂等结果不产生新红票；红字信息表须经购销双方在同一事务内
25	 * 先后确认方可开具红票，单方确认不生效，意见不一致挂起；红票确认后额度同事务恢复。
26	 * 行级争议隔离：蓝票行存在未结对账差异（OPEN/ESCALATED）时，只暂停该行的新增红冲，
27	 * 无争议行仍按原规则处理；购方未入账且没有差异的全额红冲沿用原路径，不新增挂起门槛。
28	 */
29	@Service
30	public class RedFlushService {
31	
32	    static final String ENDPOINT_CREATE = "RED_FLUSH_CREATE";
33	
34	    private final JdbcTemplate jdbc;
35	    private final CreditService creditService;
36	    private final IdempotencyService idempotencyService;
37	    private final DiscrepancyGuard discrepancyGuard;
38	    private final TransactionTemplate transactionTemplate;
39	    private final ObjectMapper objectMapper;
40	
41	    public RedFlushService(JdbcTemplate jdbc, CreditService creditService,
42	                           IdempotencyService idempotencyService, DiscrepancyGuard discrepancyGuard,
43	                           TransactionTemplate transactionTemplate, ObjectMapper objectMapper) {
44	        this.jdbc = jdbc;
45	        this.creditService = creditService;
46	        this.idempotencyService = idempotencyService;
47	        this.discrepancyGuard = discrepancyGuard;
48	        this.transactionTemplate = transactionTemplate;
49	        this.objectMapper = objectMapper;
50	    }
51	
52	    /**
53	     * 申请红字信息表（幂等）。已全额红冲蓝票返回幂等结果，不产生新红票。
54	     */
55	    public CreateRedFlushResponse createRequest(CreateRedFlushRequest request) {
56	        validateCreate(request);
57	        String fingerprint = idempotencyService.fingerprint(ENDPOINT_CREATE, request);
58	        var existing = idempotencyService.find(ENDPOINT_CREATE, request.requestId());
59	        if (existing.isPresent()) {
60	            return deserializeCreate(
61	                    idempotencyService.replayOrReject(ENDPOINT_CREATE, request, request.requestId()).body());
62	        }
63	        try {
64	            return transactionTemplate.execute(status -> doCreateRequest(request, fingerprint));
65	        } catch (DuplicateKeyException e) {
66	            return deserializeCreate(
67	                    idempotencyService.replayOrReject(ENDPOINT_CREATE, request, request.requestId()).body());
68	        }
69	    }
70	
71	    private CreateRedFlushResponse doCreateRequest(CreateRedFlushRequest request, String fingerprint) {
72	        idempotencyService.begin(ENDPOINT_CREATE, request.requestId(), fingerprint);
73	        BlueInvoiceRow blue = lockBlueByNo(request.blueInvoiceNo());
74	        BigDecimal remaining = blue.totalAmount().subtract(blue.redFlushedAmount());
75	        if (remaining.compareTo(BigDecimal.ZERO) <= 0) {
76	            // 已全额红冲：终态幂等，不产生新红票
77	            CreateRedFlushResponse response = new CreateRedFlushResponse(
78	                    "ALREADY_RED_FLUSHED", null, null, blue.invoiceNo(), BigDecimal.ZERO);
79	            idempotencyService.complete(ENDPOINT_CREATE, request.requestId(), 200, response);
80	            return response;
81	        }
82	        if (!List.of("DELIVERED", "PARTIAL_RED", "ARCHIVED").contains(blue.status())) {
83	            throw ApiException.conflict("INVALID_STATE",
84	                    "蓝票状态 " + blue.status() + " 不允许红冲（须已交付或已归档）");
85	        }
86	        // 满 72 小时未答复的差异恰满即升级（同事务落库）；未结差异只暂停对应行的新增红冲
87	        discrepancyGuard.escalateExpired(blue.id());
88	        BigDecimal pendingTotal = pendingAmount(blue.id());
89	        BigDecimal remainingForNew = remaining.subtract(pendingTotal);
90	        BigDecimal amount;
91	        List<RedLineRequest> lines = List.of();
92	        if ("FULL".equals(request.flushType())) {
93	            if (discrepancyGuard.hasBlocking(blue.id())) {
94	                throw ApiException.conflict("LINE_DISPUTED",
95	                        "蓝票存在未结对账差异，全额红冲暂停，待差异处置后重试");
96	            }
97	            if (remainingForNew.compareTo(BigDecimal.ZERO) <= 0) {
98	                throw ApiException.conflict("NO_REMAINING_BALANCE", "可红冲余额已被在途申请占满");
99	            }
100	            amount = remainingForNew;
101	        } else {
102	            Map<Integer, BigDecimal> lineBalances = lineBalances(blue.id());
103	            Map<Integer, BigDecimal> linePending = pendingLineAmounts(blue.id());
104	            amount = BigDecimal.ZERO;
105	            for (RedLineRequest line : request.lines()) {
106	                BigDecimal balance = lineBalances.get(line.lineNo());
107	                if (balance == null) {
108	                    throw ApiException.badRequest("LINE_NOT_FOUND", "蓝票不存在行号: " + line.lineNo());
109	                }
110	                if (discrepancyGuard.isLineBlocked(blue.id(), line.lineNo())) {
111	                    throw ApiException.conflict("LINE_DISPUTED",
112	                            "行 " + line.lineNo() + " 存在未结对账差异，该行新增红冲暂停，无争议行可单独申请");
113	                }
114	                BigDecimal allowed = balance.subtract(linePending.getOrDefault(line.lineNo(), BigDecimal.ZERO));
115	                if (line.amount().compareTo(allowed) > 0) {
116	                    throw ApiException.conflict("RED_FLUSH_EXCEEDS_LINE",
117	                            "行 " + line.lineNo() + " 累计红冲将超可红冲余额：可申请 " + allowed
118	                                    + "，本次 " + line.amount());
119	                }
120	                amount = amount.add(line.amount());
121	            }
122	            if (amount.compareTo(remainingForNew) > 0) {
123	                throw ApiException.conflict("RED_FLUSH_EXCEEDS_BALANCE",
124	                        "累计红冲将超可红冲余额：可申请 " + remainingForNew + "，本次 " + amount);
125	            }
126	            lines = request.lines();
127	        }
128	        long requestId = insertRequest(blue, request.flushType(), amount);
129	        String requestNo = jdbc.queryForObject(
130	                "SELECT request_no FROM red_flush_request WHERE id = ?", String.class, requestId);
131	        for (RedLineRequest line : lines) {
132	            Long blueLineId = jdbc.queryForObject(
133	                    "SELECT id FROM invoice_line WHERE invoice_id = ? AND line_no = ?",
134	                    Long.class, blue.id(), line.lineNo());
135	            jdbc.update(
136	                    "INSERT INTO red_flush_line (request_id, blue_line_id, line_no, amount) VALUES (?, ?, ?, ?)",
137	                    requestId, blueLineId, line.lineNo(), line.amount());
138	        }
139	        CreateRedFlushResponse response = new CreateRedFlushResponse(
140	                "CREATED", requestNo, "PENDING", blue.invoiceNo(), amount);
141	        idempotencyService.complete(ENDPOINT_CREATE, request.requestId(), 200, response);
142	        return response;
143	    }
144	
145	    /**
146	     * 购销双方确认。单方确认不生效；双方在同一事务内先后确认后开具红票并同事务恢复额度；
147	     * 异议则挂起。重复确认幂等返回当前状态。
148	     */
149	    public ConfirmResponse confirm(String requestNo, ConfirmRequest request) {
150	        if (request.side() == null || !List.of("SELLER", "BUYER").contains(request.side())) {
151	            throw ApiException.badRequest("VALIDATION_FAILED", "side 须为 SELLER 或 BUYER");
152	        }
153	        if (request.opinion() == null || !List.of("AGREE", "REJECT").contains(request.opinion())) {
154	            throw ApiException.badRequest("VALIDATION_FAILED", "opinion 须为 AGREE 或 REJECT");
155	        }
156	        return transactionTemplate.execute(status -> doConfirm(requestNo, request));
157	    }
158	
159	    private ConfirmResponse doConfirm(String requestNo, ConfirmRequest request) {
160	        RequestRow row = lockRequestByNo(requestNo);
161	        if ("ISSUED".equals(row.status())) {
162	            return new ConfirmResponse(requestNo, "ISSUED", row.redInvoiceNo(),
163	                    creditService.computeAvailable(sellerOf(row.blueInvoiceId())));
164	        }
165	        if ("SUSPENDED".equals(row.status())) {
166	            throw ApiException.conflict("REQUEST_SUSPENDED", "红字信息表已挂起: " + requestNo);
167	        }
168	        jdbc.update(
169	                "INSERT INTO red_flush_confirmation (request_id, side, opinion) VALUES (?, ?, ?)",
170	                row.id(), request.side(), request.opinion());
171	        if ("REJECT".equals(request.opinion())) {
172	            jdbc.update("UPDATE red_flush_request SET status = 'SUSPENDED', updated_at = CURRENT_TIMESTAMP"
173	                    + " WHERE id = ?", row.id());
174	            return new ConfirmResponse(requestNo, "SUSPENDED", null,
175	                    creditService.computeAvailable(sellerOf(row.blueInvoiceId())));
176	        }
177	        boolean sellerConfirmed = row.sellerConfirmed() || "SELLER".equals(request.side());
178	        boolean buyerConfirmed = row.buyerConfirmed() || "BUYER".equals(request.side());
179	        jdbc.update("UPDATE red_flush_request SET seller_confirmed = ?, buyer_confirmed = ?,"
180	                        + " updated_at = CURRENT_TIMESTAMP WHERE id = ?",
181	                sellerConfirmed, buyerConfirmed, row.id());
182	        if (!sellerConfirmed || !buyerConfirmed) {
183	            // 单方确认不生效
184	            return new ConfirmResponse(requestNo, "PENDING", null,
185	                    creditService.computeAvailable(sellerOf(row.blueInvoiceId())));
186	        }
187	        // 双方已确认：在同一事务内开具红票并恢复额度
188	        return issueRedInvoice(row, requestNo);
189	    }
190	
191	    private ConfirmResponse issueRedInvoice(RequestRow row, String requestNo) {
192	        BlueInvoiceRow blue = lockBlueById(row.blueInvoiceId());
193	        BigDecimal remaining = blue.totalAmount().subtract(blue.redFlushedAmount());
194	        if (remaining.compareTo(BigDecimal.ZERO) <= 0) {
195	            throw ApiException.conflict("NO_REMAINING_BALANCE", "可红冲余额不足，本次确认回滚且额度不变");
196	        }
197	        BigDecimal amount;
198	        List<RedLineRow> redLines = List.of();
199	        if ("FULL".equals(row.flushType())) {
200	            // 全额红冲：购方已入账时须已取得购方确认（双方确认已满足，此处显式校验）
201	            if (blue.buyerBooked() && !hasBuyerAgree(row.id())) {
202	                throw ApiException.conflict("BUYER_CONFIRM_REQUIRED", "购方已入账，全额红冲须取得购方确认");
203	            }
204	            amount = remaining;
205	        } else {
206	            redLines = jdbc.query(
207	                    "SELECT blue_line_id, line_no, amount FROM red_flush_line WHERE request_id = ?",
208	                    (rs, rowNum) -> new RedLineRow(rs.getLong("blue_line_id"), rs.getInt("line_no"),
209	                            rs.getBigDecimal("amount")),
210	                    row.id());
211	            amount = redLines.stream().map(RedLineRow::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
212	            Map<Integer, BigDecimal> lineBalances = lineBalances(blue.id());
213	            for (RedLineRow line : redLines) {
214	                if (line.amount().compareTo(lineBalances.get(line.lineNo())) > 0) {
215	                    throw ApiException.conflict("RED_FLUSH_EXCEEDS_LINE",
216	                            "行 " + line.lineNo() + " 累计红冲超可红冲余额，本次确认回滚且额度不变");
217	                }
218	            }
219	            if (amount.compareTo(remaining) > 0) {
220	                throw ApiException.conflict("RED_FLUSH_EXCEEDS_BALANCE",
221	                        "累计红冲超可红冲余额，本次确认回滚且额度不变");
222	            }
223	        }
224	        // 更新蓝票行项目与累计红冲金额
225	        for (RedLineRow line : redLines) {
226	            jdbc.update("UPDATE invoice_line SET red_flushed_amount = red_flushed_amount + ?"
227	                    + " WHERE id = ?", line.amount(), line.blueLineId());
228	        }
229	        BigDecimal newFlushed = blue.redFlushedAmount().add(amount);
230	        boolean fullyFlushed = newFlushed.compareTo(blue.totalAmount()) == 0;
231	        String newStatus;
232	        if ("ARCHIVED".equals(blue.status())) {
233	            // 归档票红冲不改变归档状态，仅累计红冲金额
234	            newStatus = "ARCHIVED";
235	        } else {
236	            newStatus = fullyFlushed ? "RED_FLUSHED" : "PARTIAL_RED";
237	        }
238	        jdbc.update("UPDATE invoice SET red_flushed_amount = ?, status = ?, updated_at = CURRENT_TIMESTAMP"
239	                + " WHERE id = ?", newFlushed, newStatus, blue.id());
240	        // 开具红票，引用原蓝票号码，保留完整红冲链
241	        long redInvoiceId = insertRedInvoice(blue, amount);
242	        String redInvoiceNo = jdbc.queryForObject(
243	                "SELECT invoice_no FROM invoice WHERE id = ?", String.class, redInvoiceId);
244	        // 额度在同一事务内恢复
245	        creditService.lockAccount(blue.sellerId());
246	        BigDecimal available = creditService.computeAvailable(blue.sellerId());
247	        creditService.appendLedger(blue.sellerId(), amount, "RED_CONFIRM", requestNo, available);
248	        jdbc.update("UPDATE red_flush_request SET status = 'ISSUED', red_invoice_no = ?,"
249	                + " updated_at = CURRENT_TIMESTAMP WHERE id = ?", redInvoiceNo, row.id());
250	        return new ConfirmResponse(requestNo, "ISSUED", redInvoiceNo, available);
251	    }
252	
253	    /**
254	     * 查询红字信息表：状态、行项目与双方确认轨迹，重复查询结果稳定。
255	     */
256	    public RedFlushRequestView getRequest(String requestNo) {
257	        RequestRow row = findRequestByNo(requestNo);
258	        List<RedFlushLineView> lines = jdbc.query(
259	                "SELECT line_no, amount FROM red_flush_line WHERE request_id = ? ORDER BY line_no",
260	                (rs, rowNum) -> new RedFlushLineView(rs.getInt("line_no"), rs.getBigDecimal("amount")),
261	                row.id());
262	        List<ConfirmationView> confirmations = jdbc.query(
263	                "SELECT side, opinion, created_at FROM red_flush_confirmation"
264	                        + " WHERE request_id = ? ORDER BY id",
265	                (rs, rowNum) -> new ConfirmationView(rs.getString("side"), rs.getString("opinion"),
266	                        rs.getTimestamp("created_at").toLocalDateTime()),
267	                row.id());
268	        return new RedFlushRequestView(row.requestNo(), row.blueInvoiceNo(), row.flushType(),
269	                row.totalAmount(), row.status(), row.sellerConfirmed(), row.buyerConfirmed(),
270	                row.redInvoiceNo(), lines, confirmations);
271	    }
272	
273	    private void validateCreate(CreateRedFlushRequest request) {
274	        if (request.requestId() == null || request.requestId().isBlank()) {
275	            throw ApiException.badRequest("VALIDATION_FAILED", "requestId 不能为空");
276	        }
277	        if (request.blueInvoiceNo() == null || request.blueInvoiceNo().isBlank()) {
278	            throw ApiException.badRequest("VALIDATION_FAILED", "blueInvoiceNo 不能为空");
279	        }
280	        if (request.flushType() == null || !List.of("FULL", "PARTIAL").contains(request.flushType())) {
281	            throw ApiException.badRequest("VALIDATION_FAILED", "flushType 须为 FULL 或 PARTIAL");
282	        }
283	        if ("PARTIAL".equals(request.flushType())) {
284	            if (request.lines() == null || request.lines().isEmpty()) {
285	                throw ApiException.badRequest("VALIDATION_FAILED", "部分红冲必须按行项目拆分");
286	            }
287	            for (RedLineRequest line : request.lines()) {
288	                if (line.amount() == null || line.amount().compareTo(BigDecimal.ZERO) <= 0) {
289	                    throw ApiException.badRequest("VALIDATION_FAILED", "行红冲金额必须为正数");
290	                }
291	            }
292	        }
293	    }
294	
295	    private BlueInvoiceRow lockBlueByNo(String invoiceNo) {
296	        return jdbc.query(
297	                        "SELECT id, invoice_no, seller_id, buyer_id, buyer_booked, total_amount,"
298	                                + " red_flushed_amount, status FROM invoice"
299	                                + " WHERE invoice_no = ? AND kind = 'BLUE' FOR UPDATE",
300	                        (rs, rowNum) -> mapBlue(rs), invoiceNo)
301	                .stream()
302	                .findFirst()
303	                .orElseThrow(() -> ApiException.notFound("INVOICE_NOT_FOUND", "蓝票不存在: " + invoiceNo));
304	    }
305	
306	    private BlueInvoiceRow lockBlueById(long id) {
307	        return jdbc.query(
308	                        "SELECT id, invoice_no, seller_id, buyer_id, buyer_booked, total_amount,"
309	                                + " red_flushed_amount, status FROM invoice"
310	                                + " WHERE id = ? AND kind = 'BLUE' FOR UPDATE",
311	                        (rs, rowNum) -> mapBlue(rs), id)
312	                .stream()
313	                .findFirst()
314	                .orElseThrow(() -> ApiException.notFound("INVOICE_NOT_FOUND", "蓝票不存在: " + id));
315	    }
316	
317	    private BlueInvoiceRow mapBlue(java.sql.ResultSet rs) throws java.sql.SQLException {
318	        return new BlueInvoiceRow(rs.getLong("id"), rs.getString("invoice_no"), rs.getString("seller_id"),
319	                rs.getString("buyer_id"), rs.getBoolean("buyer_booked"), rs.getBigDecimal("total_amount"),
320	                rs.getBigDecimal("red_flushed_amount"), rs.getString("status"));
321	    }
322	
323	    private RequestRow lockRequestByNo(String requestNo) {
324	        return jdbc.query(
325	                        "SELECT id, request_no, blue_invoice_id, blue_invoice_no, flush_type, total_amount,"
326	                                + " status, seller_confirmed, buyer_confirmed, red_invoice_no"
327	                                + " FROM red_flush_request WHERE request_no = ? FOR UPDATE",
328	                        (rs, rowNum) -> mapRequest(rs), requestNo)
329	                .stream()
330	                .findFirst()
331	                .orElseThrow(() -> ApiException.notFound("REQUEST_NOT_FOUND", "红字信息表不存在: " + requestNo));
332	    }
333	
334	    private RequestRow findRequestByNo(String requestNo) {
335	        return jdbc.query(
336	                        "SELECT id, request_no, blue_invoice_id, blue_invoice_no, flush_type, total_amount,"
337	                                + " status, seller_confirmed, buyer_confirmed, red_invoice_no"
338	                                + " FROM red_flush_request WHERE request_no = ?",
339	                        (rs, rowNum) -> mapRequest(rs), requestNo)
340	                .stream()
341	                .findFirst()
342	                .orElseThrow(() -> ApiException.notFound("REQUEST_NOT_FOUND", "红字信息表不存在: " + requestNo));
343	    }
344	
345	    private RequestRow mapRequest(java.sql.ResultSet rs) throws java.sql.SQLException {
346	        return new RequestRow(rs.getLong("id"), rs.getString("request_no"), rs.getLong("blue_invoice_id"),
347	                rs.getString("blue_invoice_no"), rs.getString("flush_type"), rs.getBigDecimal("total_amount"),
348	                rs.getString("status"), rs.getBoolean("seller_confirmed"), rs.getBoolean("buyer_confirmed"),
349	                rs.getString("red_invoice_no"));
350	    }
351	
352	    /**
353	     * 各行剩余可红冲余额（行金额−行累计已红冲）。
354	     */
355	    private Map<Integer, BigDecimal> lineBalances(long blueInvoiceId) {
356	        Map<Integer, BigDecimal> balances = new HashMap<>();
357	        jdbc.query("SELECT line_no, amount, red_flushed_amount FROM invoice_line WHERE invoice_id = ?",
358	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> balances.put(rs.getInt("line_no"),
359	                        rs.getBigDecimal("amount").subtract(rs.getBigDecimal("red_flushed_amount"))),
360	                blueInvoiceId);
361	        return balances;
362	    }
363	
364	    /**
