1	package com.example.starter.discrepancy;
2	
3	import java.math.BigDecimal;
4	import java.sql.Timestamp;
5	import java.time.Clock;
6	import java.time.LocalDateTime;
7	import java.util.List;
8	
9	import com.example.starter.common.ApiException;
10	import com.example.starter.idempotency.IdempotencyService;
11	import com.example.starter.redflush.RedFlushService;
12	import com.fasterxml.jackson.core.JsonProcessingException;
13	import com.fasterxml.jackson.databind.ObjectMapper;
14	import org.springframework.dao.DuplicateKeyException;
15	import org.springframework.jdbc.core.JdbcTemplate;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.support.TransactionTemplate;
18	
19	/**
20	 * 购方对账差异单服务：按蓝票行项目登记购方主张金额与合成凭据，销方确认或驳回。
21	 * 规则：单方提交不改蓝票金额与额度；未结差异（OPEN/ESCALATED）只暂停对应行的新增红冲；
22	 * 驳回解除该行暂停但保留差异记录；双方确认差异后按原红字信息表流程处理需冲减金额，
23	 * 只有红票确认生效才恢复授信额度；提交满 72 小时（UTC）未答复恰满即升级人工，不自动视为确认；
24	 * 与同一行红冲受理并发时只能一方先占该行，红冲在途/已完成则差异拒绝并保留冲突记录；
25	 * 提交与处置均按 requestId 幂等，同键同参重放首次结果，同键异参 409，
26	 * 状态与审计记录同事务提交。
27	 */
28	@Service
29	public class DiscrepancyService {
30	
31	    static final String ENDPOINT_SUBMIT = "DISCREPANCY_SUBMIT";
32	    static final String ENDPOINT_RESOLVE = "DISCREPANCY_RESOLVE";
33	
34	    private final JdbcTemplate jdbc;
35	    private final Clock clock;
36	    private final DiscrepancyGuard guard;
37	    private final RedFlushService redFlushService;
38	    private final IdempotencyService idempotencyService;
39	    private final TransactionTemplate transactionTemplate;
40	    private final ObjectMapper objectMapper;
41	
42	    public DiscrepancyService(JdbcTemplate jdbc, Clock clock, DiscrepancyGuard guard,
43	                              RedFlushService redFlushService, IdempotencyService idempotencyService,
44	                              TransactionTemplate transactionTemplate, ObjectMapper objectMapper) {
45	        this.jdbc = jdbc;
46	        this.clock = clock;
47	        this.guard = guard;
48	        this.redFlushService = redFlushService;
49	        this.idempotencyService = idempotencyService;
50	        this.transactionTemplate = transactionTemplate;
51	        this.objectMapper = objectMapper;
52	    }
53	
54	    /**
55	     * 提交差异单（幂等）。同一行红冲在途或已完成时拒绝（CONFLICT_REJECTED）并保留冲突记录。
56	     */
57	    public SubmitDiscrepancyResponse submit(SubmitDiscrepancyRequest request) {
58	        validateSubmit(request);
59	        String fingerprint = idempotencyService.fingerprint(ENDPOINT_SUBMIT, request);
60	        var existing = idempotencyService.find(ENDPOINT_SUBMIT, request.requestId());
61	        if (existing.isPresent()) {
62	            return deserializeSubmit(
63	                    idempotencyService.replayOrReject(ENDPOINT_SUBMIT, request, request.requestId()).body());
64	        }
65	        try {
66	            return transactionTemplate.execute(status -> doSubmit(request, fingerprint));
67	        } catch (DuplicateKeyException e) {
68	            // 并发同键：首次请求已提交，重放其结果
69	            return deserializeSubmit(
70	                    idempotencyService.replayOrReject(ENDPOINT_SUBMIT, request, request.requestId()).body());
71	        }
72	    }
73	
74	    private SubmitDiscrepancyResponse doSubmit(SubmitDiscrepancyRequest request, String fingerprint) {
75	        idempotencyService.begin(ENDPOINT_SUBMIT, request.requestId(), fingerprint);
76	        // 先锁蓝票行（与红冲受理同一锁序：发票→差异），保证并发时只有一方先占该行
77	        BlueRow blue = lockBlueByNo(request.blueInvoiceNo());
78	        if (!List.of("DELIVERED", "PARTIAL_RED", "ARCHIVED").contains(blue.status())) {
79	            throw ApiException.conflict("INVALID_STATE",
80	                    "蓝票状态 " + blue.status() + " 不允许登记差异（须已交付或已归档）");
81	        }
82	        guard.escalateExpired(blue.id());
83	        LineRow line = findLine(blue.id(), request.lineNo());
84	        BigDecimal diff = line.amount().subtract(request.claimedAmount());
85	        if (diff.compareTo(BigDecimal.ZERO) <= 0) {
86	            throw ApiException.badRequest("VALIDATION_FAILED",
87	                    "主张金额必须小于行金额，否则无需冲减差异");
88	        }
89	        // 冲突检测：该行（含覆盖该行的全额申请）红冲在途或已完成 → 差异拒绝并保留冲突记录
90	        String conflictReason = conflictReason(blue.id(), line.id());
91	        if (conflictReason != null) {
92	            jdbc.update(
93	                    "INSERT INTO discrepancy_conflict (blue_invoice_no, line_no, claimed_amount,"
94	                            + " evidence_ref, reason, created_at) VALUES (?, ?, ?, ?, ?, ?)",
95	                    blue.invoiceNo(), request.lineNo(), request.claimedAmount(), request.evidenceRef(),
96	                    conflictReason, Timestamp.from(clock.instant()));
97	            SubmitDiscrepancyResponse response = new SubmitDiscrepancyResponse(
98	                    "CONFLICT_REJECTED", null, null, blue.invoiceNo(), request.lineNo(), diff);
99	            idempotencyService.complete(ENDPOINT_SUBMIT, request.requestId(), 200, response);
100	            return response;
101	        }
102	        if (guard.isLineBlocked(blue.id(), request.lineNo())) {
103	            throw ApiException.conflict("DISCREPANCY_EXISTS",
104	                    "行 " + request.lineNo() + " 已存在未结差异单");
105	        }
106	        long id = insertDiscrepancy(blue, line, request, diff);
107	        String discrepancyNo = jdbc.queryForObject(
108	                "SELECT discrepancy_no FROM discrepancy WHERE id = ?", String.class, id);
109	        guard.insertEvent(id, "SUBMITTED");
110	        SubmitDiscrepancyResponse response = new SubmitDiscrepancyResponse(
111	                "SUBMITTED", discrepancyNo, "OPEN", blue.invoiceNo(), request.lineNo(), diff);
112	        idempotencyService.complete(ENDPOINT_SUBMIT, request.requestId(), 200, response);
113	        return response;
114	    }
115	
116	    /**
117	     * 销方处置差异单（幂等）：CONFIRM 确认 / REJECT 驳回。
118	     * 确认后按原红字信息表流程为需冲减金额创建 PENDING 申请，差异单本身不改额度；
119	     * 驳回解除该行暂停但保留差异记录；已升级人工的差异拒绝处置。
120	     */
121	    public ResolveDiscrepancyResponse resolve(String discrepancyNo, ResolveDiscrepancyRequest request) {
122	        if (request.requestId() == null || request.requestId().isBlank()) {
123	            throw ApiException.badRequest("VALIDATION_FAILED", "requestId 不能为空");
124	        }
125	        if (request.action() == null || !List.of("CONFIRM", "REJECT").contains(request.action())) {
126	            throw ApiException.badRequest("VALIDATION_FAILED", "action 须为 CONFIRM 或 REJECT");
127	        }
128	        ResolveCommand command = new ResolveCommand(request.requestId(), discrepancyNo, request.action());
129	        String fingerprint = idempotencyService.fingerprint(ENDPOINT_RESOLVE, command);
130	        var existing = idempotencyService.find(ENDPOINT_RESOLVE, request.requestId());
131	        if (existing.isPresent()) {
132	            return deserializeResolve(
133	                    idempotencyService.replayOrReject(ENDPOINT_RESOLVE, command, request.requestId()).body());
134	        }
135	        try {
136	            return transactionTemplate.execute(status -> doResolve(command, fingerprint));
137	        } catch (DuplicateKeyException e) {
138	            return deserializeResolve(
139	                    idempotencyService.replayOrReject(ENDPOINT_RESOLVE, command, request.requestId()).body());
140	        }
141	    }
142	
143	    private ResolveDiscrepancyResponse doResolve(ResolveCommand command, String fingerprint) {
144	        idempotencyService.begin(ENDPOINT_RESOLVE, command.requestId(), fingerprint);
145	        // 锁序与红冲受理一致：先锁发票行，再锁差异单行，避免并发死锁
146	        DiscrepancyRow probe = findByNo(command.discrepancyNo());
147	        lockBlueByNo(probe.blueInvoiceNo());
148	        DiscrepancyRow row = lockByNo(command.discrepancyNo());
149	        // 恰满 72 小时未答复即升级人工，升级后不再接受销方处置
150	        if ("OPEN".equals(row.status())) {
151	            guard.escalateIfExpired(row.id());
152	            row = lockByNo(command.discrepancyNo());
153	        }
154	        switch (row.status()) {
155	            case "ESCALATED" -> throw ApiException.conflict("DISCREPANCY_ESCALATED",
156	                    "差异单已满 72 小时未答复，升级人工处理: " + command.discrepancyNo());
157	            case "CONFIRMED", "REJECTED" -> throw ApiException.conflict("DISCREPANCY_ALREADY_RESOLVED",
158	                    "差异单已处置: " + command.discrepancyNo());
159	            default -> {
160	                // OPEN：继续处置
161	            }
162	        }
163	        Timestamp now = Timestamp.from(clock.instant());
164	        String redRequestNo = null;
165	        String newStatus;
166	        if ("CONFIRM".equals(command.action())) {
167	            newStatus = "CONFIRMED";
168	            // 双方确认差异后，按原红字信息表流程处理需冲减金额；差异单本身不改额度
169	            redRequestNo = redFlushService.createSystemRequest(
170	                    row.blueInvoiceNo(), row.lineNo(), row.diffAmount());
171	        } else {
172	            newStatus = "REJECTED";
173	        }
174	        jdbc.update("UPDATE discrepancy SET status = ?, responded_at = ?, red_request_no = ?"
175	                        + " WHERE id = ?",
176	                newStatus, now, redRequestNo, row.id());
177	        guard.insertEvent(row.id(), newStatus);
178	        ResolveDiscrepancyResponse response = new ResolveDiscrepancyResponse(
179	                command.discrepancyNo(), newStatus, redRequestNo);
180	        idempotencyService.complete(ENDPOINT_RESOLVE, command.requestId(), 200, response);
181	        return response;
182	    }
183	
184	    /**
185	     * 查询差异单：状态、需冲减金额、关联红字信息表与审计轨迹；满 72 小时未答复的
186	     * 在查询时恰满即升级（同事务落库），重复查询结果稳定。
187	     */
188	    public DiscrepancyView getDiscrepancy(String discrepancyNo) {
189	        return transactionTemplate.execute(status -> {
190	            DiscrepancyRow row = findByNo(discrepancyNo);
191	            if ("OPEN".equals(row.status())) {
192	                guard.escalateIfExpired(row.id());
193	                row = findByNo(discrepancyNo);
194	            }
195	            List<DiscrepancyEventView> events = jdbc.query(
196	                    "SELECT event, created_at FROM discrepancy_event WHERE discrepancy_id = ? ORDER BY id",
197	                    (rs, rowNum) -> new DiscrepancyEventView(rs.getString("event"),
198	                            rs.getTimestamp("created_at").toLocalDateTime()),
199	                    row.id());
200	            return new DiscrepancyView(row.discrepancyNo(), row.blueInvoiceNo(), row.lineNo(),
201	                    row.claimedAmount(), row.diffAmount(), row.evidenceRef(), row.status(),
202	                    row.redRequestNo(), row.createdAt().toLocalDateTime(),
203	                    row.respondedAt() == null ? null : row.respondedAt().toLocalDateTime(), events);
204	        });
205	    }
206	
207	    private void validateSubmit(SubmitDiscrepancyRequest request) {
208	        if (request.requestId() == null || request.requestId().isBlank()) {
209	            throw ApiException.badRequest("VALIDATION_FAILED", "requestId 不能为空");
210	        }
211	        if (request.blueInvoiceNo() == null || request.blueInvoiceNo().isBlank()) {
212	            throw ApiException.badRequest("VALIDATION_FAILED", "blueInvoiceNo 不能为空");
213	        }
214	        if (request.lineNo() == null) {
215	            throw ApiException.badRequest("VALIDATION_FAILED", "lineNo 不能为空");
216	        }
217	        if (request.evidenceRef() == null || request.evidenceRef().isBlank()) {
218	            throw ApiException.badRequest("VALIDATION_FAILED", "evidenceRef 不能为空");
219	        }
220	        if (request.claimedAmount() == null || request.claimedAmount().compareTo(BigDecimal.ZERO) < 0) {
221	            throw ApiException.badRequest("VALIDATION_FAILED", "主张金额不能为空且不得为负数");
222	        }
223	    }
224	
225	    /**
226	     * 该行红冲冲突原因：存在覆盖该行的在途（PENDING）或已完成（ISSUED）红冲申请时
227	     * 返回对应原因，否则返回 null。全额申请覆盖所有行。
228	     */
229	    private String conflictReason(long blueInvoiceId, long blueLineId) {
230	        Integer issued = jdbc.queryForObject(
231	                "SELECT COUNT(*) FROM red_flush_request r"
232	                        + " WHERE r.blue_invoice_id = ? AND r.status = 'ISSUED'"
233	                        + " AND (r.flush_type = 'FULL' OR EXISTS (SELECT 1 FROM red_flush_line rl"
234	                        + "   WHERE rl.request_id = r.id AND rl.blue_line_id = ?))",
235	                Integer.class, blueInvoiceId, blueLineId);
236	        if (issued != null && issued > 0) {
237	            return "RED_FLUSH_COMPLETED";
238	        }
239	        Integer pending = jdbc.queryForObject(
240	                "SELECT COUNT(*) FROM red_flush_request r"
241	                        + " WHERE r.blue_invoice_id = ? AND r.status = 'PENDING'"
242	                        + " AND (r.flush_type = 'FULL' OR EXISTS (SELECT 1 FROM red_flush_line rl"
243	                        + "   WHERE rl.request_id = r.id AND rl.blue_line_id = ?))",
244	                Integer.class, blueInvoiceId, blueLineId);
245	        if (pending != null && pending > 0) {
246	            return "RED_FLUSH_IN_PROGRESS";
247	        }
248	        return null;
249	    }
250	
251	    private long insertDiscrepancy(BlueRow blue, LineRow line, SubmitDiscrepancyRequest request,
252	                                   BigDecimal diff) {
253	        String tempNo = "TMP-" + java.util.UUID.randomUUID();
254	        jdbc.update(
255	                "INSERT INTO discrepancy (discrepancy_no, blue_invoice_id, blue_invoice_no, blue_line_id,"
256	                        + " line_no, claimed_amount, diff_amount, evidence_ref, status, created_at)"
257	                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'OPEN', ?)",
258	                tempNo, blue.id(), blue.invoiceNo(), line.id(), request.lineNo(), request.claimedAmount(),
259	                diff, request.evidenceRef(), Timestamp.from(clock.instant()));
260	        Long id = jdbc.queryForObject("SELECT id FROM discrepancy WHERE discrepancy_no = ?",
261	                Long.class, tempNo);
262	        String discrepancyNo = "DIF" + String.format("%08d", id);
263	        jdbc.update("UPDATE discrepancy SET discrepancy_no = ? WHERE id = ?", discrepancyNo, id);
264	        return id;
265	    }
266	
267	    private BlueRow lockBlueByNo(String invoiceNo) {
268	        return jdbc.query(
269	                        "SELECT id, invoice_no, status FROM invoice"
270	                                + " WHERE invoice_no = ? AND kind = 'BLUE' FOR UPDATE",
271	                        (rs, rowNum) -> new BlueRow(rs.getLong("id"), rs.getString("invoice_no"),
272	                                rs.getString("status")),
273	                        invoiceNo)
274	                .stream()
275	                .findFirst()
276	                .orElseThrow(() -> ApiException.notFound("INVOICE_NOT_FOUND", "蓝票不存在: " + invoiceNo));
277	    }
278	
279	    private LineRow findLine(long blueInvoiceId, int lineNo) {
280	        return jdbc.query(
281	                        "SELECT id, amount FROM invoice_line WHERE invoice_id = ? AND line_no = ?",
282	                        (rs, rowNum) -> new LineRow(rs.getLong("id"), rs.getBigDecimal("amount")),
283	                        blueInvoiceId, lineNo)
284	                .stream()
285	                .findFirst()
286	                .orElseThrow(() -> ApiException.badRequest("LINE_NOT_FOUND", "蓝票不存在行号: " + lineNo));
287	    }
288	
289	    private DiscrepancyRow lockByNo(String discrepancyNo) {
290	        return jdbc.query(
291	                        "SELECT id, discrepancy_no, blue_invoice_no, line_no, claimed_amount, diff_amount,"
292	                                + " evidence_ref, status, red_request_no, created_at, responded_at"
293	                                + " FROM discrepancy WHERE discrepancy_no = ? FOR UPDATE",
294	                        (rs, rowNum) -> mapRow(rs), discrepancyNo)
295	                .stream()
296	                .findFirst()
297	                .orElseThrow(() -> ApiException.notFound("DISCREPANCY_NOT_FOUND", "差异单不存在: " + discrepancyNo));
298	    }
299	
300	    private DiscrepancyRow findByNo(String discrepancyNo) {
301	        return jdbc.query(
302	                        "SELECT id, discrepancy_no, blue_invoice_no, line_no, claimed_amount, diff_amount,"
303	                                + " evidence_ref, status, red_request_no, created_at, responded_at"
304	                                + " FROM discrepancy WHERE discrepancy_no = ?",
305	                        (rs, rowNum) -> mapRow(rs), discrepancyNo)
306	                .stream()
307	                .findFirst()
308	                .orElseThrow(() -> ApiException.notFound("DISCREPANCY_NOT_FOUND", "差异单不存在: " + discrepancyNo));
309	    }
310	
311	    private DiscrepancyRow mapRow(java.sql.ResultSet rs) throws java.sql.SQLException {
312	        return new DiscrepancyRow(rs.getLong("id"), rs.getString("discrepancy_no"),
313	                rs.getString("blue_invoice_no"), rs.getInt("line_no"),
314	                rs.getBigDecimal("claimed_amount"), rs.getBigDecimal("diff_amount"),
315	                rs.getString("evidence_ref"), rs.getString("status"), rs.getString("red_request_no"),
316	                rs.getTimestamp("created_at"), rs.getTimestamp("responded_at"));
317	    }
318	
319	    private SubmitDiscrepancyResponse deserializeSubmit(String body) {
320	        try {
321	            return objectMapper.readValue(body, SubmitDiscrepancyResponse.class);
322	        } catch (JsonProcessingException e) {
323	            throw new IllegalStateException("幂等响应反序列化失败", e);
324	        }
325	    }
326	
327	    private ResolveDiscrepancyResponse deserializeResolve(String body) {
328	        try {
329	            return objectMapper.readValue(body, ResolveDiscrepancyResponse.class);
330	        } catch (JsonProcessingException e) {
331	            throw new IllegalStateException("幂等响应反序列化失败", e);
332	        }
333	    }
334	
335	    /**
336	     * 蓝票内部行视图。
337	     */
338	    record BlueRow(long id, String invoiceNo, String status) {
339	    }
340	
341	    /**
342	     * 蓝票行内部视图。
343	     */
344	    record LineRow(long id, BigDecimal amount) {
345	    }
346	
347	    /**
348	     * 差异单内部行视图。
349	     */
350	    record DiscrepancyRow(long id, String discrepancyNo, String blueInvoiceNo, int lineNo,
351	                          BigDecimal claimedAmount, BigDecimal diffAmount, String evidenceRef,
352	                          String status, String redRequestNo, Timestamp createdAt, Timestamp respondedAt) {
353	    }
354	
355	    /**
356	     * 差异提交请求（幂等指纹覆盖全部字段）。
357	     */
358	    public record SubmitDiscrepancyRequest(String requestId, String blueInvoiceNo, Integer lineNo,
359	                                           BigDecimal claimedAmount, String evidenceRef) {
360	    }
361	
362	    /**
363	     * 差异提交响应。result=CONFLICT_REJECTED 时该行红冲在途或已完成，差异拒绝且冲突记录已保留。
364	     */
365	    public record SubmitDiscrepancyResponse(String result, String discrepancyNo, String status,
366	                                            String blueInvoiceNo, Integer lineNo, BigDecimal diffAmount) {
367	    }
368	
369	    /**
370	     * 差异处置请求。
371	     */
372	    public record ResolveDiscrepancyRequest(String requestId, String action) {
373	    }
374	
375	    /**
376	     * 差异处置命令（幂等指纹覆盖 requestId、差异单号与处置动作）。
377	     */
378	    record ResolveCommand(String requestId, String discrepancyNo, String action) {
379	    }
380	
381	    /**
382	     * 差异处置响应。status=CONFIRMED 时 redRequestNo 为按原红字信息表流程创建的申请编号。
383	     */
384	    public record ResolveDiscrepancyResponse(String discrepancyNo, String status, String redRequestNo) {
385	    }
386	
387	    /**
388	     * 差异单审计事件视图。
389	     */
390	    public record DiscrepancyEventView(String event, LocalDateTime createdAt) {
391	    }
392	
393	    /**
394	     * 差异单详情视图。createdAt/respondedAt 为 UTC 时间。
395	     */
396	    public record DiscrepancyView(String discrepancyNo, String blueInvoiceNo, int lineNo,
397	                                  BigDecimal claimedAmount, BigDecimal diffAmount, String evidenceRef,
398	                                  String status, String redRequestNo, LocalDateTime createdAt,
399	                                  LocalDateTime respondedAt, List<DiscrepancyEventView> events) {
400	    }
401	}
